const inbound = $('Set Follow-Up Target').first().json || {};
const rows = Array.isArray($json) ? $json : Array.isArray($json.data) ? $json.data : Array.isArray($json.body) ? $json.body : [];
const row = rows[0] || {};
const payload = row.payload || {};
const lastSequence = String(inbound.last_sequence_result || '').toLowerCase();
const maxAttempts = Math.max(Number(inbound.max_attempts_per_prospect || 3), 1);
const maxFollowUpSteps = Math.max(maxAttempts - 1, 1);
let followUpStep = 1;
const match = lastSequence.match(/follow_up_sent_(\d+)/i);
if (match) {
  followUpStep = Math.min(Number(match[1] || 0) + 1, maxFollowUpSteps);
} else if (lastSequence === 'sent_v3') {
  followUpStep = 1;
}
const isFinalFollowUp = followUpStep >= maxFollowUpSteps;
const delayDays = followUpStep === 1 ? 4 : 7;
const nextActionAtAfter = isFinalFollowUp ? null : new Date(Date.now() + delayDays * 86400000).toISOString();
const auditFormUrl = payload.audit_form_url || inbound.audit_form_url || '';
const canSend = Boolean(inbound.prospect_id && inbound.target_email && row.pack_id);
let failureReason = '';
if (!inbound.prospect_id) failureReason = 'missing_prospect_id';
else if (!inbound.target_email) failureReason = 'missing_target_email';
else if (!row.pack_id) failureReason = 'missing_reference_pack';
return [{ json: {
  ...inbound,
  pack_id: row.pack_id || inbound.last_pack_id || null,
  executive_letter: payload.executive_letter || '',
  executive_letter_html: payload.executive_letter_html || '',
  audit_form_url: auditFormUrl,
  recommended_offer: payload.recommended_offer || '',
  recommended_use_case: payload.recommended_use_case || payload.best_selling_use_case || '',
  probable_quick_wins: payload.probable_quick_wins || [],
  organization_summary: payload.organization_summary || '',
  follow_up_step: followUpStep,
  max_follow_up_steps: maxFollowUpSteps,
  is_final_follow_up: isFinalFollowUp,
  next_action_at_after: nextActionAtAfter,
  can_send: canSend,
  send_failure_reason: failureReason,
  pack_payload: payload
} }];

const ctx = $('Build Follow-Up Context').first().json || {};
let aiBody = '';
try {
  const response = $input.first().json || {};
  aiBody = (((response.choices || [])[0] || {}).message || {}).content || '';
} catch (e) {}
const fallback = ctx.follow_up_step >= 2
  ? `Bonjour,\n\nJe me permets un dernier suivi concernant la proposition d'audit IA que nous vous avions adressée pour ${ctx.organization_name || 'votre organisation'}. Si le sujet reste pertinent, nous pouvons convenir d'un court échange ici : ${ctx.booking_link_45min || 'https://calendly.com/contact-transferai/30min'}. ${ctx.audit_form_url ? `Le formulaire préparatoire reste également disponible ici : ${ctx.audit_form_url}. ` : ''}\n\nBien cordialement,\nTransferAI`
  : `Bonjour,\n\nJe reviens vers vous à propos de notre proposition d'audit IA pour ${ctx.organization_name || 'votre organisation'}. Nous pensons que ${ctx.recommended_use_case || 'le cas d’usage identifié'} pourrait constituer une première piste utile à explorer. Vous pouvez réserver un échange ici : ${ctx.booking_link_45min || 'https://calendly.com/contact-transferai/30min'}. ${ctx.audit_form_url ? `Le formulaire préparatoire est accessible ici : ${ctx.audit_form_url}. ` : ''}\n\nBien cordialement,\nTransferAI`;
const bodyText = String(aiBody || fallback).trim();
const subject = ctx.follow_up_step >= 2
  ? `Dernier suivi - proposition d'audit IA pour ${ctx.organization_name || 'votre organisation'}`
  : `Suite à notre proposition d'audit IA pour ${ctx.organization_name || 'votre organisation'}`;
return [{ json: {
  ...ctx,
  email_subject: subject,
  email_text: bodyText,
  email_html: bodyText.replace(/\n/g, '<br>')
} }];

const ctx = $('Build Follow-Up Email Payload').first().json || {};
const resend = $input.first().json || {};
const resendId = resend.id || (resend.data && resend.data.id) || null;
const errorMessage = resend.message || (resend.error && resend.error.message) || '';
return [{ json: {
  ...ctx,
  resend_response: resend,
  resend_id: resendId,
  send_ok: Boolean(resendId),
  send_failure_reason: resendId ? null : (errorMessage || ctx.send_failure_reason || 'follow_up_send_failed'),
  sent_at: new Date().toISOString()
} }];
